  HEADLINE,
  INSTRUMENT_MIX,
  JUNE_FLOW,
  KOREA_SENSITIVITY,
  METER_COMPARE,
  MONTHLY_FLOW_PATH,
  OWNERSHIP_NODES,
  REGION_SHARES,
  SOURCE_NOTE,
  fmtPct,
  fmtPp,
  fmtUsdBn,
  jurisdictionScatter,
  mismatchBars,
  ownershipRegionRollup,
} from "@/data/fiscal-industrial-policy-geography-202608-data";

// viz-types: sensitivity dual+waterfall, ownership ladder+donut, instrument stacked+scatter, battery ladder+monthly area | layout: default

type ViewId = "sensitivity" | "ownership" | "instruments" | "battery";
type Universe = "core" | "alt";
type BatteryFilter = "all" | "US" | "Canada" | "Mexico" | "NA";

const SKY = "#0ea5e9";
const ROSE = "#f43f5e";
const VIOLET = "#8b5cf6";
const SLATE = "#64748b";
const AMBER = "#f59e0b";
const TEAL = "#14b8a6";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function FiscalIndustrialPolicyGeography202608Dashboard() {
