    const core = KOREA_SENSITIVITY[0];
    const alt = KOREA_SENSITIVITY[1];
    return [
      {
        label: "NA core",
        value: core.northAmericaPct,
        fill: SKY,
      },
      {
        label: "E. Asia core",
        value: core.eastAsiaPct,
        fill: ROSE,
      },
      {
        label: "NA after Korea",
        value: alt.northAmericaPct,
        fill: "#38bdf8",
