                    tick={{ fontSize: 11 }}
                    unit="%"
                    domain={[0, 80]}
                  />
                  <YAxis
                    yAxisId="total"
                    orientation="right"
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Area
                    yAxisId="share"
                    type="monotone"
                    dataKey="RoW"
                    stackId="1"
                    fill={SLATE}
                    stroke={SLATE}
                    fillOpacity={0.35}
                  />
                  <Area
                    yAxisId="share"
                    type="monotone"
                    dataKey="US"
                    stackId="1"
                    fill={SKY}
                    stroke={SKY}
                    fillOpacity={0.45}
                  />
                  <Area
                    yAxisId="share"
                    type="monotone"
                    dataKey="EU"
                    stackId="1"
                    fill={VIOLET}
                    stroke={VIOLET}
                    fillOpacity={0.45}
                  />
                  <Area
                    yAxisId="share"
                    type="monotone"
                    dataKey="China"
                    stackId="1"
                    fill={ROSE}
                    stroke={ROSE}
                    fillOpacity={0.45}
                  />
                  <Line
                    yAxisId="total"
                    type="monotone"
                    dataKey="total"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
